import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { Stepper, StepperProps } from "./stepper";
import { useState } from "react";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

// The current step is controlled by the parent, so the stories keep it in local state and let each
// step's onNavigate callback move there.
const InteractiveStepper = (props: StepperProps) => {
  const [currentStep, setCurrentStep] = useState(props.currentStep);
  const onNavigate = props.onNavigate.map((navigate, index) => () => {
    navigate();
    setCurrentStep(index + 1);
  });
  return <Stepper {...props} currentStep={currentStep} onNavigate={onNavigate} />;
};

const threeSteps = [fn(), fn(), fn()];

const meta = {
  title: "Primitives/Stepper",
  component: Stepper,
  parameters: {
    docs: {
      description: {
        component:
          "Heading plus a row of numbered step buttons for multi-step flows, e.g. the ticket purchase. Steps " +
          "before `currentStep` render as complete with a check mark, the current one is highlighted and the " +
          "rest are inactive. Every step is clickable and calls its `onNavigate` callback; the parent owns " +
          "`currentStep`. With five or more steps the row switches to a compact layout.",
      },
    },
  },
  args: {
    heading: "Köp biljetter",
    headingComponent: "h1",
    currentStep: 1,
    onNavigate: threeSteps,
  },
  render: (args) => <InteractiveStepper {...args} />,
} satisfies Meta<typeof Stepper>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantStepStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Step states and step count" variantType="other">
      <Variant label="first of three steps active">
        <Stepper {...args} heading="Steg 1 av 3" currentStep={1} onNavigate={threeSteps} />
      </Variant>
      <Variant label="second of four steps active (first complete)">
        <Stepper {...args} heading="Steg 2 av 4" currentStep={2} onNavigate={[fn(), fn(), fn(), fn()]} />
      </Variant>
      <Variant label="last of three steps active">
        <Stepper {...args} heading="Steg 3 av 3" currentStep={3} onNavigate={threeSteps} />
      </Variant>
      <Variant label="five steps (compact layout)">
        <Stepper {...args} heading="Steg 3 av 5" currentStep={3} onNavigate={[fn(), fn(), fn(), fn(), fn()]} />
      </Variant>
    </ShowcaseLayout>
  ),
};

const navigateToStepThree = fn();

export const TestNavigate: Story = {
  args: {
    onNavigate: [fn(), fn(), navigateToStepThree],
  },
  play: async ({ canvasElement }) => {
    navigateToStepThree.mockClear();
    const canvas = within(canvasElement);
    const stepThree = canvas.getByRole("button", { name: "Steg 3 av 3, status inactive" });
    await userEvent.click(stepThree);
    await expect(navigateToStepThree).toHaveBeenCalledTimes(1);
    await expect(canvas.getByRole("button", { name: "Steg 3 av 3, status active" })).toHaveAttribute(
      "aria-current",
      "step",
    );
    await expect(canvas.getByRole("button", { name: "Steg 1 av 3, status complete" })).toBeVisible();
  },
};
