import { Fragment } from "react";
import styles from "./stepper.module.less";
import { Icon } from "@/core/components/primitives/icon/icon";
import { motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { HeadingLevel } from "@/core/components/primitives/banner/banner";

export type StepperProps = {
  heading: string;
  /** Html element for the heading, e.g. `h1` */
  headingComponent: HeadingLevel;
  /** 1-based. Steps before it render as complete (check mark), steps after it as inactive */
  currentStep: number;
  /** One callback per step, called when that step is clicked. The array length defines the number of steps */
  onNavigate: Array<() => void>;
};

export const Stepper = ({ heading, headingComponent, currentStep, onNavigate }: StepperProps) => {
  const { t } = useTranslation();
  const HeadingComponent = headingComponent;
  const totalSteps = onNavigate.length;

  const onHandleStepClick = (step: number) => {
    onNavigate[step - 1]();
  };

  return (
    <div className={styles.wrapper}>
      <HeadingComponent className={styles.heading}>{heading}</HeadingComponent>

      <nav
        className={multipleClassNames(styles.stepWrapper, totalSteps >= 5 && styles.manySteps)}
        aria-label={t("stepperGroupAriaLabel", { totalSteps })}
      >
        {Array.from({ length: totalSteps }, (_, index) => {
          const step = index + 1;
          const isLastStep = step === totalSteps;
          const stepStatus = step === currentStep ? "active" : step < currentStep ? "complete" : "inactive";

          return (
            <Fragment key={step}>
              <motion.button
                key={`step-${step}`}
                animate={stepStatus}
                className={styles.step}
                layout="size"
                type="button"
                onClick={() => onHandleStepClick(step)}
                initial={false}
                transition={{
                  duration: 0.3,
                  type: "tween",
                  ease: "circOut",
                }}
                data-status={stepStatus}
                aria-label={t("stepperStepAriaLabel", { currentStep: step, totalSteps, status: stepStatus })}
                aria-current={stepStatus === "active" ? "step" : undefined}
                aria-disabled={stepStatus === "inactive"}
              >
                {stepStatus === "complete" ? <Icon name="done" /> : <span>{step}</span>}
              </motion.button>
              {!isLastStep && <span className={styles.divider}></span>}
            </Fragment>
          );
        })}
      </nav>
    </div>
  );
};
